#!/usr/bin/env python3
"""Generate /app/gates.txt: computes fib(isqrt(N)) mod 2^32.

Semantics of sim.c: each step, signals are evaluated in increasing index order.
A gate reading a source with LOWER index sees this step's value (combinational);
a gate reading a source with HIGHER index sees the previous step's value (register).

Layout: 0..31 inputs (self copies), then registers, then constants, then
combinational logic, then the 32 output copies (last 32 lines, LSB first).
"""
import sys

WSQ = 22          # width of isqrt remainder arithmetic
ITERS = 4         # fibonacci iterations per clock cycle


class Net:
    def __init__(self):
        self.lines = {}
        self.n = 0
        self.cache = {}

    def alloc(self, text=None):
        i = self.n
        self.n += 1
        if text is not None:
            self.lines[i] = text
        return i

    def set(self, i, text):
        self.lines[i] = text

    def gate(self, op, a, b=None):
        if op in ('&', '|', '^') and a > b:
            a, b = b, a
        key = (op, a, b)
        if key in self.cache:
            return self.cache[key]
        if b is None:
            text = 'out%d = ~out%d' % (0, a)  # placeholder, fixed below
            i = self.alloc()
            self.set(i, '~out%d' % a)
        else:
            i = self.alloc()
            self.set(i, 'out%d %s out%d' % (a, op, b))
        self.cache[key] = i
        return i

    def emit(self):
        out = []
        for i in range(self.n):
            out.append('out%d = %s' % (i, self.lines[i]))
        return '\n'.join(out) + '\n'


net = Net()


def AND(a, b):
    if a is False or b is False:
        return False
    if a is True:
        return b
    if b is True:
        return a
    if a == b:
        return a
    return net.gate('&', a, b)


def OR(a, b):
    if a is True or b is True:
        return True
    if a is False:
        return b
    if b is False:
        return a
    if a == b:
        return a
    return net.gate('|', a, b)


def NOT(a):
    if a is True:
        return False
    if a is False:
        return True
    return net.gate('~', a)


def XOR(a, b):
    if a is True:
        return NOT(b)
    if b is True:
        return NOT(a)
    if a is False:
        return b
    if b is False:
        return a
    if a == b:
        return False
    return net.gate('^', a, b)


def MUX(sel, x, y):
    """sel ? x : y"""
    if sel is True:
        return x
    if sel is False:
        return y
    return XOR(y, AND(XOR(x, y), sel))


def ADD(x, y):
    c = False
    res = []
    for i in range(len(x)):
        t = XOR(x[i], y[i])
        res.append(XOR(t, c))
        c = OR(AND(x[i], y[i]), AND(c, t))
    return res


def SUB(x, y):
    """returns (x-y, borrow_out); borrow_out == 1 iff x < y"""
    bo = False
    res = []
    for i in range(len(x)):
        t = XOR(x[i], y[i])
        res.append(XOR(t, bo))
        bo = OR(AND(NOT(x[i]), y[i]), AND(bo, NOT(t)))
    return res, bo


