IN = [net.alloc('out%d' % i) for i in range(32)]        # 0..31, self copies
reg_a = [net.alloc() for _ in range(32)]
reg_b = [net.alloc() for _ in range(32)]
reg_c = [net.alloc() for _ in range(16)]
reg_started = net.alloc()
CONST0 = net.alloc('0')
CONST1 = net.alloc('1')


def sig(x):
    """materialize a constant as a signal index"""
    if x is True:
        return CONST1
    if x is False:
        return CONST0
    return x


# ------------------------------------------------------------------- isqrt
rem = [False] * WSQ
root = [False] * 16          # LSB first
for i in range(15, -1, -1):
    rem = [IN[2 * i], IN[2 * i + 1]] + rem[:WSQ - 2]      # rem = 4*rem + digit
    t = [True, False] + root[:WSQ - 2]                    # t = 4*root + 1
    diff, borrow = SUB(rem, t)
    ge = NOT(borrow)
    rem = [MUX(ge, diff[j], rem[j]) for j in range(WSQ)]
    root = [ge] + root[:15]                               # root = 2*root + ge
K = root

# --------------------------------------------------------- fibonacci engine
started = reg_started
first = NOT(started)

ai, bi, ci = list(reg_a), list(reg_b), list(reg_c)
for _ in range(ITERS):
    nz = False
    for bit in ci:
        nz = OR(nz, bit)
    s = ADD(ai, bi)
    a_new = [MUX(nz, bi[j], ai[j]) for j in range(32)]
    b_new = [MUX(nz, s[j], bi[j]) for j in range(32)]
    bor = nz
    c_new = []
    for j in range(16):
        c_new.append(XOR(ci[j], bor))
        bor = AND(NOT(ci[j]), bor)
    ai, bi, ci = a_new, b_new, c_new

# register next-state, with first-cycle load: a=0, b=1, cnt=K
a_next = [AND(ai[j], started) for j in range(32)]
b_next = [OR(first, bi[0])] + [AND(bi[j], started) for j in range(1, 32)]
c_next = [MUX(started, ci[j], K[j]) for j in range(16)]

for j in range(32):
    net.set(reg_a[j], 'out%d' % sig(a_next[j]))
    net.set(reg_b[j], 'out%d' % sig(b_next[j]))
for j in range(16):
    net.set(reg_c[j], 'out%d' % sig(c_next[j]))
net.set(reg_started, 'out%d' % CONST1)

# ------------------------------------------------------------------ outputs
for j in range(32):
    net.alloc('out%d' % reg_a[j])

text = net.emit()
path = sys.argv[1] if len(sys.argv) > 1 else '/app/gates.txt'
with open(path, 'w') as f:
    f.write(text)
print('signals: %d' % net.n)

